package main

import (
	"encoding/json"
	"fmt"
	"net/http"
	"os"
	"strings"

	"github.com/spf13/viper"
)

type Scheme uint

const (
	HTTP Scheme = iota
	HTTPS
)

func (s Scheme) String() string {
	if s == HTTPS {
		return "https"
	}
	return "http"
}

func (s Scheme) MarshalJSON() ([]byte, error) {
	return json.Marshal(s.String())
}

type config struct {
	LogLevel string         `json:"logLevel,omitempty"`
	UI       uiConfig       `json:"ui,omitempty"`
	Cors     corsConfig     `json:"cors,omitempty"`
	Cache    cacheConfig    `json:"cache,omitempty"`
	Server   serverConfig   `json:"server,omitempty"`
	Database databaseConfig `json:"database,omitempty"`
}

type uiConfig struct {
	Enabled bool `json:"enabled"`
}

type corsConfig struct {
	Enabled        bool     `json:"enabled"`
	AllowedOrigins []string `json:"allowedOrigins,omitempty"`
}

type memoryCacheConfig struct {
	Enabled bool `json:"enabled"`
	Items   int  `json:"items,omitempty"`
}

type cacheConfig struct {
	Memory memoryCacheConfig `json:"memory,omitempty"`
}

type serverConfig struct {
	Host      string `json:"host,omitempty"`
	Protocol  Scheme `json:"protocol"`
	HTTPPort  int    `json:"httpPort,omitempty"`
	HTTPSPort int    `json:"httpsPort,omitempty"`
	GRPCPort  int    `json:"grpcPort,omitempty"`
	CertFile  string `json:"certFile,omitempty"`
	CertKey   string `json:"certKey,omitempty"`
}

type databaseConfig struct {
	MigrationsPath string `json:"migrationsPath,omitempty"`
	URL            string `json:"url,omitempty"`
}

func defaultConfig() *config {
	return &config{
		LogLevel: "INFO",

		UI: uiConfig{
			Enabled: true,
		},

		Cors: corsConfig{
			Enabled:        false,
			AllowedOrigins: []string{"*"},
		},

		Cache: cacheConfig{
			Memory: memoryCacheConfig{
				Enabled: false,
				Items:   500,
			},
		},

		Server: serverConfig{
			Host:      "0.0.0.0",
			Protocol:  HTTP,
			HTTPPort:  8080,
			HTTPSPort: 443,
			GRPCPort:  9000,
		},

		Database: databaseConfig{
			URL:            "file:/var/opt/flipt/flipt.db",
			MigrationsPath: "/etc/flipt/config/migrations",
		},
	}
}

const (
	// Logging
	cfgLogLevel = "log.level"

	// UI
	cfgUIEnabled = "ui.enabled"

	// CORS
	cfgCorsEnabled        = "cors.enabled"
	cfgCorsAllowedOrigins = "cors.allowed_origins"

	// Cache
	cfgCacheMemoryEnabled = "cache.memory.enabled"
	cfgCacheMemoryItems   = "cache.memory.items"

	// Server
	cfgServerHost      = "server.host"
	cfgServerProtocol  = "server.protocol"
	cfgServerHTTPPort  = "server.http_port"
	cfgServerHTTPSPort = "server.https_port"
	cfgServerGRPCPort  = "server.grpc_port"
	cfgServerCertFile  = "server.cert_file"
	cfgServerCertKey   = "server.cert_key"

	// DB
	cfgDBURL            = "db.url"
	cfgDBMigrationsPath = "db.migrations.path"
)

func configure(path string) (*config, error) {
	v := viper.New()
	v.SetEnvPrefix("FLIPT")
	v.SetEnvKeyReplacer(strings.NewReplacer(".", "_"))
	v.AutomaticEnv()

	v.SetConfigFile(path)

	if err := v.ReadInConfig(); err != nil {
		return nil, err
	}

	cfg := defaultConfig()

	// Logging
	if v.IsSet(cfgLogLevel) {
		cfg.LogLevel = v.GetString(cfgLogLevel)
	}

	// UI
	if v.IsSet(cfgUIEnabled) {
		cfg.UI.Enabled = v.GetBool(cfgUIEnabled)
	}

	// CORS
	if v.IsSet(cfgCorsEnabled) {
		cfg.Cors.Enabled = v.GetBool(cfgCorsEnabled)
	}
	if v.IsSet(cfgCorsAllowedOrigins) {
		cfg.Cors.AllowedOrigins = v.GetStringSlice(cfgCorsAllowedOrigins)
	}

	// Cache
	if v.IsSet(cfgCacheMemoryEnabled) {
		cfg.Cache.Memory.Enabled = v.GetBool(cfgCacheMemoryEnabled)
	}
	if v.IsSet(cfgCacheMemoryItems) {
		cfg.Cache.Memory.Items = v.GetInt(cfgCacheMemoryItems)
	}

	// Server
	if v.IsSet(cfgServerHost) {
		cfg.Server.Host = v.GetString(cfgServerHost)
	}
	if v.IsSet(cfgServerProtocol) {
		switch strings.ToLower(v.GetString(cfgServerProtocol)) {
		case "http":
			cfg.Server.Protocol = HTTP
		case "https":
			cfg.Server.Protocol = HTTPS
		default:
			return nil, fmt.Errorf("invalid server protocol %q", v.GetString(cfgServerProtocol))
		}
	}
	if v.IsSet(cfgServerHTTPPort) {
		cfg.Server.HTTPPort = v.GetInt(cfgServerHTTPPort)
	}
	if v.IsSet(cfgServerHTTPSPort) {
		cfg.Server.HTTPSPort = v.GetInt(cfgServerHTTPSPort)
	}
	if v.IsSet(cfgServerGRPCPort) {
		cfg.Server.GRPCPort = v.GetInt(cfgServerGRPCPort)
	}
	if v.IsSet(cfgServerCertFile) {
		cfg.Server.CertFile = v.GetString(cfgServerCertFile)
	}
	if v.IsSet(cfgServerCertKey) {
		cfg.Server.CertKey = v.GetString(cfgServerCertKey)
	}

	// DB
	if v.IsSet(cfgDBURL) {
		cfg.Database.URL = v.GetString(cfgDBURL)
	}
	if v.IsSet(cfgDBMigrationsPath) {
		cfg.Database.MigrationsPath = v.GetString(cfgDBMigrationsPath)
	}

	return cfg, cfg.validate()
}

func (c *config) validate() error {
	if c.Server.Protocol != HTTPS {
		return nil
	}
	if c.Server.CertFile == "" {
		return fmt.Errorf("cert_file cannot be empty when using HTTPS")
	}
	if c.Server.CertKey == "" {
		return fmt.Errorf("cert_key cannot be empty when using HTTPS")
	}
	if _, err := os.Stat(c.Server.CertFile); err != nil {
		return fmt.Errorf("cannot find TLS cert_file at %q", c.Server.CertFile)
	}
	if _, err := os.Stat(c.Server.CertKey); err != nil {
		return fmt.Errorf("cannot find TLS cert_key at %q", c.Server.CertKey)
	}
	return nil
}

func (c *config) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	out, err := json.Marshal(c)
	if err != nil {
		logger.WithError(err).Error("getting config")
		w.WriteHeader(http.StatusInternalServerError)
		return
	}

	if _, err = w.Write(out); err != nil {
		logger.WithError(err).Error("writing response")
		w.WriteHeader(http.StatusInternalServerError)
		return
	}

	w.WriteHeader(http.StatusOK)
}

type info struct {
	Version   string `json:"version,omitempty"`
	Commit    string `json:"commit,omitempty"`
	BuildDate string `json:"buildDate,omitempty"`
	GoVersion string `json:"goVersion,omitempty"`
}

func (i info) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	out, err := json.Marshal(i)
	if err != nil {
		logger.WithError(err).Error("getting metadata")
		w.WriteHeader(http.StatusInternalServerError)
		return
	}

	if _, err = w.Write(out); err != nil {
		logger.WithError(err).Error("writing response")
		w.WriteHeader(http.StatusInternalServerError)
		return
	}

	w.WriteHeader(http.StatusOK)
}
package main

import (
	"fmt"
	"io/ioutil"
	"net/http"
	"net/http/httptest"
	"os"
	"path/filepath"
	"reflect"
	"strings"
	"testing"
)

func writeConfig(t *testing.T, contents string) (string, func()) {
	t.Helper()
	dir, err := ioutil.TempDir("", "flipt-config-")
	if err != nil {
		t.Fatal(err)
	}
	cleanup := func() { os.RemoveAll(dir) }
	path := filepath.Join(dir, "config.yml")
	if err := ioutil.WriteFile(path, []byte(contents), 0600); err != nil {
		t.Fatal(err)
	}
	return path, cleanup
}

func TestConfigureDefaultsAndOverrides(t *testing.T) {
	cfg, err := configure("../../config/default.yml")
	if err != nil {
		t.Fatal(err)
	}
	if !reflect.DeepEqual(cfg, defaultConfig()) {
		t.Fatalf("default configuration differs: %#v", cfg)
	}

	path, cleanup := writeConfig(t, "log:\n  level: WARN\nui:\n  enabled: false\ncors:\n  enabled: true\n  allowed_origins: foo.com\ncache:\n  memory:\n    enabled: true\n    items: 5000\nserver:\n  host: 127.0.0.1\n  http_port: 8081\n  grpc_port: 9001\ndb:\n  url: postgres://postgres@localhost:5432/flipt?sslmode=disable\n  migrations:\n    path: ./config/migrations\n")
	defer cleanup()
	cfg, err = configure(path)
	if err != nil {
		t.Fatal(err)
	}
	if cfg.LogLevel != "WARN" || cfg.UI.Enabled || !cfg.Cors.Enabled || !reflect.DeepEqual(cfg.Cors.AllowedOrigins, []string{"foo.com"}) || !cfg.Cache.Memory.Enabled || cfg.Cache.Memory.Items != 5000 || cfg.Server.Host != "127.0.0.1" || cfg.Server.HTTPPort != 8081 || cfg.Server.GRPCPort != 9001 || cfg.Database.URL != "postgres://postgres@localhost:5432/flipt?sslmode=disable" || cfg.Database.MigrationsPath != "./config/migrations" {
		t.Fatalf("unexpected configuration: %#v", cfg)
	}

	path, cleanup = writeConfig(t, "cors:\n  allowed_origins:\n    - foo.com\n")
	defer cleanup()
	cfg, err = configure(path)
	if err != nil || !reflect.DeepEqual(cfg.Cors.AllowedOrigins, []string{"foo.com"}) {
		t.Fatalf("list origins: %#v, %v", cfg, err)
	}

	if err := os.Setenv("FLIPT_SERVER_HTTP_PORT", "8181"); err != nil {
		t.Fatal(err)
	}
	defer os.Unsetenv("FLIPT_SERVER_HTTP_PORT")
	cfg, err = configure(path)
	if err != nil || cfg.Server.HTTPPort != 8181 {
		t.Fatalf("environment override: %#v, %v", cfg, err)
	}
}

func TestHTTPSValidation(t *testing.T) {
	cfg := defaultConfig()
	cfg.Server.Protocol = HTTPS
	for _, tc := range []struct {
		cert, key, want string
	}{
		{"", "", "cert_file cannot be empty when using HTTPS"},
		{"cert.pem", "", "cert_key cannot be empty when using HTTPS"},
		{"missing.pem", "missing.key", "cannot find TLS cert_file at \"missing.pem\""},
	} {
		cfg.Server.CertFile, cfg.Server.CertKey = tc.cert, tc.key
		if err := cfg.validate(); err == nil || err.Error() != tc.want {
			t.Fatalf("validate(%q, %q) = %v; want %q", tc.cert, tc.key, err, tc.want)
		}
	}

	cert, cleanup := writeConfig(t, "certificate")
	defer cleanup()
	cfg.Server.CertFile, cfg.Server.CertKey = cert, "missing.key"
	if err := cfg.validate(); err == nil || err.Error() != "cannot find TLS cert_key at \"missing.key\"" {
		t.Fatalf("missing key: %v", err)
	}
	cfg.Server.CertKey = cert
	if err := cfg.validate(); err != nil {
		t.Fatal(err)
	}
	path, cleanup := writeConfig(t, fmt.Sprintf("server:\n  protocol: https\n  https_port: 8080\n  cert_file: %q\n  cert_key: %q\n", cert, cert))
	defer cleanup()
	loaded, err := configure(path)
	if err != nil || loaded.Server.Protocol != HTTPS || loaded.Server.HTTPSPort != 8080 || loaded.Server.CertFile != cert || loaded.Server.CertKey != cert {
		t.Fatalf("HTTPS configuration: %#v, %v", loaded, err)
	}
	cfg.Server.Protocol = HTTP
	cfg.Server.CertFile = ""
	cfg.Server.CertKey = ""
	if err := cfg.validate(); err != nil {
		t.Fatal(err)
	}

	path, cleanup = writeConfig(t, "server:\n  protocol: https\n")
	defer cleanup()
	if _, err := configure(path); err == nil || err.Error() != "cert_file cannot be empty when using HTTPS" {
		t.Fatalf("configure validation: %v", err)
	}
}

func TestMetadataHandlers(t *testing.T) {
	for _, handler := range []http.Handler{defaultConfig(), info{Version: "test"}} {
		recorder := httptest.NewRecorder()
		handler.ServeHTTP(recorder, httptest.NewRequest(http.MethodGet, "/", nil))
		if recorder.Code != http.StatusOK || strings.TrimSpace(recorder.Body.String()) == "" {
			t.Fatalf("response: %d %q", recorder.Code, recorder.Body.String())
		}
	}
	if HTTPS.String() != "https" || HTTP.String() != "http" {
		t.Fatal("unexpected scheme strings")
	}
}
